if (typeof useWS !== 'undefined') {
   useWS('/api/ws/custom/siparis_guncellendi', (payload) => {
       // Refresh via finding the refresh button since RecordsManager doesn't expose loadItems directly
       const btns = document.querySelectorAll('.mdi-refresh');
       if(btns.length > 0 && btns[0].parentElement) {
           btns[0].parentElement.click();
       }
   });
}
return {};

const dialogOpen = ref(false);
const activeOrder = ref(null);

const isRunning = ref(false);
const baslamaZamani = ref(0);
const saniye = ref(0);
let intv = null;

const timerStr = computed(() => {
   const m = Math.floor(saniye.value / 60).toString().padStart(2, '0');
   const s = (saniye.value % 60).toString().padStart(2, '0');
   return `${m}:${s}`;
});

const selectOrder = (item) => {
   activeOrder.value = item;
   saniye.value = 0;
   isRunning.value = false;
   dialogOpen.value = true;
};

const startTimer = async () => {
   isRunning.value = true;
   baslamaZamani.value = Date.now();
   intv = setInterval(() => { saniye.value++; }, 1000);
   try {
      await $fetch('/api/custom/mes/operations', { method: 'POST', body: { action: 'islem_baslat', data: { is_emri_id: activeOrder.value.id } } });
   } catch(e){}
};

const pauseTimer = () => {
   isRunning.value = false;
   if(intv) clearInterval(intv);
};

const finishOrder = async (formData) => {
   isRunning.value = false;
   if(intv) clearInterval(intv);

   try {
      await $fetch('/api/custom/mes/operations', { method: 'POST', body: { 
         action: 'islem_bitir', 
         data: { is_emri_id: activeOrder.value.id, uretilen: Number(formData.uretilen || 0), fire: Number(formData.fire || 0), net_sure_sn: saniye.value, gorev_adi: formData.gorev_adi } 
      } });
      dialogOpen.value = false;

      const btns = document.querySelectorAll('.mdi-refresh');
      if(btns.length > 0 && btns[0].parentElement) btns[0].parentElement.click();

   } catch(e) {
      alert("Hata oluştu");
   }
};

if (typeof useWS !== 'undefined') {
   useWS('/api/ws/custom/siparis_guncellendi', (payload) => {
       const btns = document.querySelectorAll('.mdi-refresh');
       if(btns.length > 0 && btns[0].parentElement) btns[0].parentElement.click();
   });
}

return { dialogOpen, activeOrder, selectOrder, isRunning, saniye, timerStr, startTimer, pauseTimer, finishOrder };

const dialogOpen = ref(false);
const activeItem = ref(null);

const openKantar = (item) => {
   activeItem.value = item;
   dialogOpen.value = true;
};

const kabulEt = async (formData) => {
   try {
      const res = await $fetch('/api/custom/mes/operations', { method: 'POST', body: { 
         action: 'fason_kabul', 
         data: { takip_no: activeItem.value.takip_no, tartilan_agirlik: Number(formData.tartilan_agirlik) } 
      } });
      dialogOpen.value = false;
      alert(res.adet + ' Adet stoğa eklendi!');

      const btns = document.querySelectorAll('.mdi-refresh');
      if(btns.length > 0 && btns[0].parentElement) btns[0].parentElement.click();

   } catch(e) {
      alert("Hata oluştu");
   }
};

return { dialogOpen, openKantar, kabulEt };
